#include <stdio.h>

/* dobroDoDigitado le um inteiro digitado e imprime o dobro dele.
   O n += n dobra o valor e o printf mostra o resultado — os dois ja estao
   escritos. Falta a linha que LE o numero digitado para dentro de n.
   Nao imprima pergunta nenhuma: a saida deste desafio e so a linha do dobro. */
void dobroDoDigitado(void) {
    int n = 0;

    /* leia aqui o inteiro digitado para dentro de n (scanf, %d e o &) */

    n += n;
    printf("%d\n", n);
}

